return $input.all().filter(item => {
  const msg = item.json?.message ?? {};
  return !!(msg.text || msg.caption);
});

const records = $input.all();
const chatId = $('Telegram_Uzenet').item.json.message.chat.id;
const firstName = $('Telegram_Uzenet').item.json.message.chat.first_name || 'Dolgozó';
let message = `📊 **${firstName} - Mai munkaidő státusz:**\n\n`;
if (records.length === 0) {
  message += '❌ Ma még nincs rögzített munkaidő.\n\n';
  message += '💡 Küldj egy üzenetet, például:\n';
  message += '• "Ma 8 órákat dolgoztam"\n';
  message += '• "Kezdtem 9:00"';
} else {
  message += `✅ **${records.length}** bejegyzés rögzítve ma.\n\n`;
  records.forEach((record, i) => {
    const m = record.json['Megjegyzés'] || record.json['Projekt'] || 'Nincs megjegyzés';
    message += `${i+1}. ${m}\n`;
  });
}
return [{ json: { message, chatId } }];

const records = $input.all();
const chatId = $('Telegram_Uzenet').item.json.message.chat.id;
const firstName = $('Telegram_Uzenet').item.json.message.chat.first_name || 'Dolgozó';
let message = `📅 **${firstName} - Heti munkaidő összесítő:**\n\n`;
if (records.length === 0) {
  message += '❌ Az elmúlt 7 napban nincs rögzített munkaidő.\n';
} else {
  message += `✅ **${records.length}** bejegyzés az elmúlt 7 napban.\n\n`;
  const byDate = {};
  records.forEach(r => {
    const d = r.json['Dátum'] || 'Ismeretlen';
    if (!byDate[d]) byDate[d] = [];
    byDate[d].push(r.json['Megjegyzés'] || r.json['Projekt'] || 'Nincs megjegyzés');
  });
  Object.keys(byDate).sort().reverse().forEach(d => {
    message += `\n📆 **${d}**\n`;
    byDate[d].forEach((m, i) => { message += `  ${i+1}. ${m}\n`; });
  });
}
message += '\n💡 Használd a /statusz parancsot a mai státuszhoz.';
return [{ json: { message, chatId } }];

